1	/**
2	 * Declarative navigation tree. Each item names the permission and flag that
3	 * gate it, which is how the sidebar stays role-aware without ad-hoc
4	 * conditionals: `visibleNav()` is the only place that decides what a given
5	 * actor sees, and it decides by calling `can()` and consulting the flag
6	 * snapshot rather than by branching on `actor.role`.
7	 */
8	import { isEnabled } from "@/lib/feature-flags";
9	import { can } from "@/lib/permissions";
10	import type { FeatureFlagKey, FeatureFlagSnapshot } from "@/types/feature-flag";
11	import type { Actor } from "@/types/member";
12	import type { PermissionAction, PermissionResource } from "@/types/permission";
13	
14	export type NavItem = {
15	  key: string;
16	  label: string;
17	  segment: string;
18	  icon?: string;
19	  action?: PermissionAction;
20	  flag?: FeatureFlagKey;
21	  children?: readonly NavItem[];
22	};
23	
24	export const SIDEBAR_NAV: readonly NavItem[] = [
25	  {
26	    key: "overview",
27	    label: "Overview",
