54	        label: "Board",
55	        segment: "board",
56	        action: "issue:read",
57	        flag: "kanban_board",
58	      },
59	      {
60	        key: "issues.search",
61	        label: "Advanced search",
62	        segment: "search",
63	        action: "issue:read",
64	        flag: "advanced_search",
65	      },
66	    ],
67	  },
68	  {
69	    key: "inbox",
70	    label: "Inbox",
71	    segment: "inbox",
72	    icon: "bell",
73	    action: "notification:read",
74	  },
75	  {
76	    key: "activity",
77	    label: "Activity",
78	    segment: "activity",
