import type { CalendarDate, IsoTimestamp } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

const MINUTE_MS = 60_000;
const HOUR_MS = 60 * MINUTE_MS;
const DAY_MS = 24 * HOUR_MS;
const WEEK_MS = 7 * DAY_MS;

export function now(): IsoTimestamp {
  return toIsoTimestamp(new Date());
}

/** True for a real `YYYY-MM-DD` day: `2026-02-30` and `2026-13-01` are not. */
export function isCalendarDate(value: string): value is CalendarDate {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const time = Date.parse(`${value}T00:00:00.000Z`);
  return (
    Number.isFinite(time) &&
    new Date(time).toISOString().slice(0, 10) === value
  );
}

/**
 * The exclusive upper bound of a `due_before` filter. A calendar date covers
 * its whole UTC day, so the bound is the next midnight; a timestamp is the
 * instant itself.
 */
export function dueBeforeCutoff(value: CalendarDate | IsoTimestamp): IsoTimestamp {
  if (isCalendarDate(value)) {
    return toIsoTimestamp(new Date(Date.parse(`${value}T00:00:00.000Z`) + DAY_MS));
  }
  return toIsoTimestamp(parseIso(value));
}

