/** Statuses that count as closed for stats, digests and overdue checks. */
export const CLOSED_ISSUE_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

/** Group names a status filter may use in place of a list of statuses. */
export type IssueStatusGroup = "open" | "closed";

export const ISSUE_STATUS_GROUPS: readonly IssueStatusGroup[] = ["open", "closed"];

/** Members of each group: `open` is every status that is not closed. */
export const ISSUE_STATUS_GROUP_MEMBERS: Readonly<
  Record<IssueStatusGroup, readonly IssueStatus[]>
> = {
  open: ISSUE_STATUSES.filter((status) => !CLOSED_ISSUE_STATUSES.includes(status)),
  closed: CLOSED_ISSUE_STATUSES,
};

/** A status as written in a filter: one status, or a group that stands for several. */
export type IssueStatusToken = IssueStatus | IssueStatusGroup;

export function isIssueStatusToken(value: string): value is IssueStatusToken {
  return (
    ISSUE_STATUSES.includes(value as IssueStatus) ||
    ISSUE_STATUS_GROUPS.includes(value as IssueStatusGroup)
  );
}

/** Expands groups into their members; keeps first-seen order, drops repeats. */
export function expandIssueStatuses(
  tokens: readonly IssueStatusToken[],
): readonly IssueStatus[] {
  const expanded = new Set<IssueStatus>();
  for (const token of tokens) {
    const members = ISSUE_STATUS_GROUPS.includes(token as IssueStatusGroup)
      ? ISSUE_STATUS_GROUP_MEMBERS[token as IssueStatusGroup]
      : [token as IssueStatus];
    for (const status of members) expanded.add(status);
  }
  return [...expanded];
}

