  readonly projectId?: ProjectId;
  readonly status?: readonly IssueStatusToken[];
  readonly priority?: readonly IssuePriority[];
  readonly assigneeId?: IssueFilterUser | null;
  readonly authorId?: IssueFilterUser;
  /** Every listed label must be on the issue. */
  readonly labelIds?: readonly LabelId[];
  readonly query?: string;
  /** Issues due strictly before this instant, or on or before this UTC day. */
  readonly dueBefore?: CalendarDate | IsoTimestamp;
  /** Adds archived issues to the live ones. */
  readonly includeArchived?: boolean;
  /** Lists archived issues and nothing else. */
  readonly archivedOnly?: boolean;
}

