import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import { cleanup as rtlCleanup, render, screen } from "@testing-library/react";

vi.mock("@/lib/id", () => import("./server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);
vi.mock("next/navigation", () => ({
  useRouter: () => ({ push: vi.fn(), replace: vi.fn(), refresh: vi.fn() }),
}));

import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as issueService from "@/server/services/issue-service";
import { parseIssueFilterParams, readableRecord } from "@/hooks/issue-filter-params";
import { issueFilterSchema } from "@/schemas/issue";
import { exportIssuesSchema } from "@/schemas/export";
import { AppSidebar } from "@/components/domain/nav/app-sidebar";
import { makeActor, makeOrganization } from "./helpers/factories";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
import type { Tenant } from "./server/_support/fixtures";

let cleanupDb: () => void;
let t: Tenant;

beforeAll(async () => {
  cleanupDb = await useTemporaryDatabase();
  t = await createTenant("scratchverify");
});
afterAll(() => cleanupDb());

async function make(
  title: string,
  o: { assigneeId?: string | null; dueAt?: string | null; status?: "backlog" | "done" | "todo"; labelIds?: string[] } = {},
) {
  const number = await issueRepo.nextIssueNumber(t.org.id, t.project.id);
  return issueRepo.insertIssue(
    {
      ...issueInput(t.org.id, t.project.id, {
        title,
        assigneeId: (o.assigneeId ?? null) as never,
        dueAt: o.dueAt ?? null,
      }),
      status: o.status ?? "backlog",
      labelIds: (o.labelIds ?? []) as never,
    },
    t.userIds.owner,
    number,
  );
}

describe("scratch verification of the six reports", () => {
  let mine: string;
  let unassigned: string;
  let both: string;
  let onlyOne: string;
  let due9: string;
  let due10: string;
  let archived: string;
  let done: string;
  let l1: string;
  let l2: string;

  beforeAll(async () => {
    const l1r = await labelRepo.insertLabel({ orgId: t.org.id, name: "bug", color: "#ff0000", description: null });
    const l2r = await labelRepo.insertLabel({ orgId: t.org.id, name: "regression", color: "#00ff00", description: null });
    l1 = l1r.id;
    l2 = l2r.id;
    mine = (await make("mine", { assigneeId: t.userIds.member, status: "todo" })).id;
    unassigned = (await make("unassigned")).id;
    both = (await make("both labels", { labelIds: [l1, l2] })).id;
    onlyOne = (await make("only bug", { labelIds: [l1] })).id;
    due9 = (await make("due morning 9th", { dueAt: "2026-10-09T09:00:00.000Z" })).id;
    due10 = (await make("due 10th", { dueAt: "2026-10-10T00:00:00.000Z" })).id;
    done = (await make("done one", { status: "done" })).id;
    const arch = await make("archived one", { assigneeId: null });
    archived = arch.id;
    await issueRepo.archiveIssue(t.org.id, arch.id);
  });

  it("1. assignee=me resolves to the acting user in the service", async () => {
    const filter = parseIssueFilterParams(new URLSearchParams("assignee=me"));
    const page = await issueService.listIssues(t.actors.member, { ...filter, orgId: t.org.id, limit: 50, cursor: null } as never);
    expect(page.items.map((i) => i.id)).toEqual([mine]);
    expect(page.total).toBe(1);
  });

  it("2. assignee=none returns only unassigned issues", async () => {
    const page = await issueRepo.listIssues({ orgId: t.org.id, limit: 50, cursor: null, assigneeId: null });
    expect(page.items.map((i) => i.id)).toContain(unassigned);
    expect(page.items.every((i) => i.assigneeId === null)).toBe(true);
    expect(page.total).toBe(page.items.length);
  });

  it("3. two labels are all-of and the total agrees", async () => {
    const page = await issueRepo.listIssues({ orgId: t.org.id, limit: 50, cursor: null, labelIds: [l1, l2] as never });
    expect(page.items.map((i) => i.id)).toEqual([both]);
    expect(page.total).toBe(1);
    expect(page.items.map((i) => i.id)).not.toContain(onlyOne);
  });

  it("4. due_before calendar date includes the whole day, excludes the next", async () => {
    const page = await issueRepo.listIssues({ orgId: t.org.id, limit: 50, cursor: null, dueBefore: "2026-10-09" as never });
    expect(page.items.map((i) => i.id)).toContain(due9);
    expect(page.items.map((i) => i.id)).not.toContain(due10);
    const stamp = await issueRepo.listIssues({ orgId: t.org.id, limit: 50, cursor: null, dueBefore: "2026-10-09T09:00:00.000Z" as never });
    expect(stamp.items.map((i) => i.id)).not.toContain(due9);
  });

  it("4b. schema accepts a date and refuses an impossible one", () => {
    expect(issueFilterSchema.safeParse({ orgId: t.org.id, dueBefore: "2026-10-09" }).success).toBe(true);
    expect(issueFilterSchema.safeParse({ orgId: t.org.id, dueBefore: "2026-02-30" }).success).toBe(false);
    expect(issueFilterSchema.safeParse({ orgId: t.org.id, dueBefore: "2026-10-09T10:00:00Z" }).success).toBe(true);
  });

  it("5. status=open is accepted by codec, schema and repository", async () => {
    const filter = parseIssueFilterParams(new URLSearchParams("status=open"));
    expect(filter.status).toEqual(["backlog", "todo", "in_progress", "in_review"]);
    expect(issueFilterSchema.safeParse({ orgId: t.org.id, status: ["open"] }).success).toBe(true);
    expect(issueFilterSchema.safeParse({ orgId: t.org.id, status: ["bogus"] }).success).toBe(false);
    expect(exportIssuesSchema.safeParse({ orgId: t.org.id, status: ["open"] }).success).toBe(true);
    const page = await issueRepo.listIssues({ orgId: t.org.id, limit: 50, cursor: null, status: ["open"] });
    expect(page.items.map((i) => i.id)).not.toContain(done);
    expect(page.items.map((i) => i.id)).toContain(mine);
  });

  it("6. archived=only lists archived rows alone; archived=1 mixes", async () => {
    const only = await issueRepo.listIssues({ orgId: t.org.id, limit: 50, cursor: null, archivedOnly: true });
    expect(only.items.map((i) => i.id)).toEqual([archived]);
    expect(only.total).toBe(1);
    const live = await issueRepo.listIssues({ orgId: t.org.id, limit: 50, cursor: null });
    expect(live.items.map((i) => i.id)).not.toContain(archived);
    const mixed = await issueRepo.listIssues({ orgId: t.org.id, limit: 50, cursor: null, includeArchived: true });
    expect(mixed.items.map((i) => i.id)).toContain(archived);
    expect(mixed.total).toBe(live.total + 1);
    const parsed = parseIssueFilterParams(new URLSearchParams("archived=only"));
    expect(parsed.archivedOnly).toBe(true);
    expect(parsed.includeArchived).toBeUndefined();
  });

  it("readableRecord joins repeated keys", () => {
    const r = readableRecord({ status: ["todo", "done"], q: "x" });
    expect(parseIssueFilterParams(r).status).toEqual(["todo", "done"]);
  });

  it("sidebar 'Assigned to me' links to issues?assignee=me", () => {
    const org = makeOrganization();
    const actor = makeActor({ role: "owner", orgId: org.id });
    render(
      <AppSidebar org={org} actor={actor} flags={{ kanban_board: false, ai_issue_summary: false, command_palette: false, activity_feed: false, public_projects: false, webhooks: false, csv_export: false, digest_email: false, issue_templates: false, advanced_search: false }} projects={[]} pathname="/acme" />,
    );
    const link = screen.getByRole("link", { name: "Assigned to me" });
    expect(link.getAttribute("href")).toBe("/" + org.slug + "/issues?assignee=me");
    rtlCleanup();
  });
});

